window.TEACH_SLIDES['7-21'] = [{"k": "title", "html": "<p class=\"ts-kicker\">ថ្នាក់ទី ៧ · មេរៀនទី ២១</p><h1>ក្រាបសសរ</h1><p class=\"ts-sub\">១ ផ្នែក</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">មេរៀនទី ២១</p><h2>គោលបំណង</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">1.</span><div>ធ្វើតារាងបំណែងចែកទិន្នន័យ</div></li><li class=\"lab\"><span class=\"lb\">2.</span><div>បកស្រាយទិន្នន័យតាមក្រាបសសរ</div></li><li class=\"lab\"><span class=\"lb\">3.</span><div>សង់ក្រាបសសរ ។</div></li></ul>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>1. ក្រាបសសរ</h1>"}, {"k": "", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h2>1. ក្រាបសសរ</h2><p>ក្រាបសសរ ជាក្រាបដែលមានរាងចតុកោណកែងតាងឱ្យទិន្នន័យស្ថិតិ ដើម្បីងាយស្រួលក្នុងការបកស្រាយទិន្នន័យ ។ <br> ស្ថិតិ ជាការប្រមូលនិងវិភាគទិន្នន័យជាលេខក្នុងបរិមាណច្រើន ដើម្បីធ្វើសេចក្តីសន្និដ្ឋានរួម ។ <br> គេប្រើក្រាបសសរដើម្បីបង្ហាញព័ត៌មាន ហើយគេប្រើក្រាបសសរភ្លោះ ដើម្បីប្រៀបធៀបទិន្នន័យដែលមានពីរឬច្រើនប្រភេទខុសគ្នាក្នុងអំឡុងពេលតែមួយ ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. ក្រាបសសរ</p><h2>ឧទាហរណ៍ <span class=\"ts-pg\">(១/២)</span></h2><p>៖ គេស្រង់អាយុសិស្ស 40 នាក់ក្នុងថ្នាក់រៀនមួយបានដូចខាងក្រោម ៖</p><table class=\"ts-table\"><tr><td>11</td><td>11</td><td>12</td><td>13</td><td>14</td><td>12</td><td>13</td><td>12</td><td>11</td><td>14</td></tr><tr><td>14</td><td>11</td><td>12</td><td>12</td><td>12</td><td>14</td><td>13</td><td>13</td><td>13</td><td>13</td></tr><tr><td>11</td><td>12</td><td>13</td><td>12</td><td>14</td><td>11</td><td>13</td><td>12</td><td>11</td><td>14</td></tr><tr><td>12</td><td>13</td><td>12</td><td>12</td><td>13</td><td>12</td><td>12</td><td>11</td><td>14</td><td>13</td></tr></table><p>អាយុសិស្សដែលគេស្រង់បានខាងលើហៅថា ទិន្នន័យ ។ ទិន្នន័យខាងលើពិបាកឱ្យគេដឹងថា តើសិស្សអាយុប៉ុន្មានឆ្នាំមានចំនួនច្រើនជាងគេ និងសិស្សអាយុប៉ុន្មានឆ្នាំមានចំនួនតិចជាងគេ? ដូច្នេះគេត្រូវរៀបចំទិន្នន័យដាក់ក្នុងតារាងដូចខាងក្រោម ។ <br> ដំបូងគេត្រូវពិនិត្យមើលអាយុសិស្សដែលតិចជាងគេ និងអាយុសិស្សដែលច្រើនជាងគេ រួចគេធ្វើតារាងបែងចែកចំនួនអាយុសិស្សទៅតាមឆ្នាំ ។ គេបានតារាងមួយហៅថា តារាងបំណែងចែកទិន្នន័យ ។</p><table class=\"ts-table\"><tr><td>អាយុសិស្ស(ឆ្នាំ)</td><td>ចំនួនសិស្ស</td></tr><tr><td>11</td><td>8</td></tr><tr><td>12</td><td>14</td></tr><tr><td>13</td><td>11</td></tr><tr><td>14</td><td>7</td></tr></table><p>តាមតារាងនេះ គេអាចដឹងភ្លាមថា</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. ក្រាបសសរ</p><h2>ឧទាហរណ៍ <span class=\"ts-pg\">(២/២)</span></h2><ul class=\"ts-bullets\"><li>សិស្សភាគច្រើនមានអាយុ 12 ឆ្នាំ</li><li>សិស្សភាគតិចមានអាយុ 14 ឆ្នាំ</li></ul><p>ដើម្បីឱ្យកាន់តែងាយជាងនេះ គេក៏អាចបកស្រាយតារាងបំណែងចែកទិន្នន័យជាក្រាបសសរផងដែរ ។</p><ul class=\"ts-bullets\"><li>តាងអ័ក្សដេក ជាអាយុសិស្ស</li><li>តាងអ័ក្សឈរ ជាចំនួនសិស្ស</li><li>ដោយយក 1 ឯកតាតាងសិស្សម្នាក់ ។</li></ul><p>រូបតាងនេះគេហៅថា ក្រាបសសរ ។</p><p><b>បកស្រាយ</b></p><ul class=\"ts-bullets\"><li>សសរទី 1 បង្ហាញថាសិស្សអាយុ 11 ឆ្នាំ មានចំនួន 8 នាក់</li><li>សសរទី 2 បង្ហាញថាសិស្សអាយុ 12 ឆ្នាំ មានចំនួន 14 នាក់</li><li>សសរទី 3 បង្ហាញថាសិស្សអាយុ 13 ឆ្នាំ មានចំនួន 11 នាក់</li><li>សសរទី 4 បង្ហាញថាសិស្សអាយុ 14 ឆ្នាំ មានចំនួន 7 នាក់ ។</li></ul><p>គេអាចសង់ក្រាបសសរ ជាទម្រង់ផ្ដេកដោយយកអ័ក្សដេកតាងចំនួនសិស្ស និងអ័ក្សឈរតាងអាយុសិស្ស ។ <br></p><p>គេប្រើក្រាបសសរសម្រាប់បង្ហាញព័ត៌មាន ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. ក្រាបសសរ</p><h2>លំហាត់គំរូ 1</h2><p>៖ ក្រាបសសរខាងក្រោមបង្ហាញពីអាយុកាលគិតជាឆ្នាំ នៃគ្រឿងអគ្គិសនីប្រើប្រាស់ក្នុងផ្ទះ ។</p><ol class=\"ts-bullets\"><li>ឆ្នាំងបាយខ្សែភ្លើង</li><li>ម៉ាស៊ីនបោកខោអាវ</li><li>ទូរទឹកកក</li><li>ចង្ក្រានអគ្គិសនី</li><li>ម៉ាស៊ីនអាំងសាច់</li><li>ម៉ាស៊ីនត្រជាក់</li><li>ទូរទស្សន៍</li><li>ម៉ាស៊ីនដេរ</li></ol><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>តើគ្រឿងអគ្គិសនីណាមានអាយុកាលប្រើប្រាស់ច្រើនជាងគេ ហើយគ្រឿងអគ្គិសនីណាមានអាយុកាលប្រើប្រាស់តិចជាងគេ?</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>រកភាគរយនៃគ្រឿងអគ្គិសនីមានអាយុកាលប្រើប្រាស់តិចជាង 12 ឆ្នាំ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. ក្រាបសសរ</p><h2>ដំណោះស្រាយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>តាមក្រាប ម៉ាស៊ីនដេរមានអាយុកាលវែងជាងគេ គឺ \\(22\\) ឆ្នាំ។ ម៉ាស៊ីនបោកខោអាវនិងទូរទស្សន៍មានអាយុកាលខ្លីជាងគេ គឺ \\(11\\) ឆ្នាំ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គ្រឿងអគ្គិសនីដែលមានអាយុកាលតិចជាង \\(12\\) ឆ្នាំមាន \\(2\\) ប្រភេទ ក្នុងចំណោម \\(8\\) ប្រភេទ។ គេបាន ៖ \\[\\begin{aligned}\n    p &amp;= \\frac{2}{8}\\times100\\% \\\\\n      &amp;=25\\%\n    \\end{aligned}\\]</div></li></ul><p>ដូចនេះ ម៉ាស៊ីនដេរមានអាយុកាលវែងជាងគេ ហើយគ្រឿងអគ្គិសនីដែលមានអាយុកាលតិចជាង \\(12\\) ឆ្នាំមាន \\(25\\%\\)។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. ក្រាបសសរ</p><h2>លំហាត់គំរូ 2 <span class=\"ts-pg\">(១/២)</span></h2><p>៖ គ្រួសារមួយបានកត់ត្រាការចំណាយនិងការសន្សំប្រចាំខែ ដើម្បីរៀបចំផែនការហិរញ្ញវត្ថុរយៈពេលវែង ។ ការចំណាយនិងការសន្សំមានបង្ហាញក្នុងតារាងខាងក្រោម៖</p><table class=\"ts-table\"><tr><td>បរិយាយ</td><td>ចំនួនទឹកប្រាក់</td></tr><tr><td>កាតទូរសព្ទ</td><td>20 000 ៛</td></tr><tr><td>ថ្លៃឈ្នួលផ្ទះ</td><td>500 000 ៛</td></tr><tr><td>ទូទាត់សងកម្ចីធនាគារ</td><td>450 000 ៛</td></tr><tr><td>សាំងម៉ូតូ</td><td>70 000 ៛</td></tr><tr><td>អគ្គិសនី</td><td>90 000 ៛</td></tr><tr><td>ម្ហូបអាហារ</td><td>700 000 ៛</td></tr><tr><td>សន្សំ</td><td>50 000 ៛</td></tr><tr><td>សម្លៀកបំពាក់</td><td>150 000 ៛</td></tr></table>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. ក្រាបសសរ</p><h2>លំហាត់គំរូ 2 <span class=\"ts-pg\">(២/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>សង់ក្រាបសសរដោយប្រើប្រាស់ទិន្នន័យក្នុងតារាងខាងលើ</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តើគ្រួសារនេះត្រូវការប្រាក់ចំណូលប៉ុន្មានសម្រាប់ការចំណាយនិងការសន្សំទាំងនេះ?</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>តើគ្រួសារនេះចំណាយប្រាក់លើអ្វីច្រើនជាងគេបំផុត?</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>តើគ្រួសារនេះចំណាយប្រាក់លើអ្វីតិចជាងគេបំផុត?</div></li><li class=\"lab\"><span class=\"lb\">ង.</span><div>ផ្អែកលើក្រាបសសរនេះ តើអ្នកគួរផ្តល់ដំបូន្មានដល់គ្រួសារមួយនេះដូចម្តេចក្នុងការគ្រប់គ្រងប្រាក់ និងការធ្វើផែនការហិរញ្ញវត្ថុ?</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. ក្រាបសសរ</p><h2>ដំណោះស្រាយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>យកអ័ក្សដេកតាងប្រភេទការចំណាយនិងការសន្សំ ហើយអ័ក្សឈរតាងទឹកប្រាក់គិតជារៀល។ ខ្នាតមួយជំហានស្មើ \\(100~000\\) ៛។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>បូកការចំណាយនិងការសន្សំទាំងអស់ ៖ \\[\\begin{aligned}\n    T &amp;=20~000+500~000 \\\\\n      &amp;\\quad+450~000+70~000 \\\\\n      &amp;\\quad+90~000+700~000 \\\\\n      &amp;\\quad+50~000+150~000 \\\\\n      &amp;=2~030~000~\\text{៛}\n    \\end{aligned}\\] ដូចនេះ គ្រួសារត្រូវការប្រាក់ចំណូលយ៉ាងតិច \\(2~030~000\\) ៛ ក្នុងមួយខែ។</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>ការចំណាយច្រើនជាងគេគឺម្ហូបអាហារ មានចំនួន \\(700~000\\) ៛ ក្នុងមួយខែ។</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>ការចំណាយតិចជាងគេគឺកាតទូរសព្ទ មានចំនួន \\(20~000\\) ៛ ក្នុងមួយខែ។</div></li><li class=\"lab\"><span class=\"lb\">ង.</span><div>បើទម្រង់ចំណាយនៅដដែល គ្រួសារគួរបម្រុងប្រាក់យ៉ាងតិច \\(2~030~000\\) ៛ ក្នុងមួយខែ។ គួរកត់ត្រាចំណាយនិងការសន្សំជាប្រចាំ និងពិនិត្យចំណាយដែលអាចកាត់បន្ថយ ដើម្បីបង្កើនប្រាក់សន្សំសម្រាប់គ្រាអាសន្ននិងអនាគត។</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. ក្រាបសសរ</p><h2>ប្រតិបត្តិ 1</h2><p>៖ <br> តារាងខាងក្រោមនេះជាលទ្ធផលសិស្សសាលារៀន 3 គឺ M N និង Q បានប្រឡងជាប់សញ្ញាបត្រមធ្យមសិក្សាបឋមភូមិ ។</p><table class=\"ts-table\"><tr><td>សាលា</td><td>M</td><td>N</td><td>Q</td></tr><tr><td>ចំនួនសិស្សប្រឡង</td><td>120</td><td>150</td><td>95</td></tr><tr><td>ចំនួនសិស្សប្រឡងជាប់</td><td>25</td><td>30</td><td>18</td></tr></table><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>បង្ហាញអត្រាសិស្សប្រឡងជាប់នៃសាលានីមួយៗជាក្រាប</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តើសាលាណាមានភាគរយសិស្សជាប់ច្រើនជាងគេ?</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. ក្រាបសសរ</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>អត្រាជាប់ស្មើចំនួនសិស្សជាប់ចែកនឹងចំនួនសិស្សប្រឡង រួចគុណនឹង \\(100\\%\\) ៖ \\[\\begin{aligned}\n    p_M&amp;=\\frac{25}{120}\\times100\\%\\approx20.83\\% \\\\\n    p_N&amp;=\\frac{30}{150}\\times100\\%=20\\% \\\\\n    p_Q&amp;=\\frac{18}{95}\\times100\\%\\approx18.95\\%\n    \\end{aligned}\\] ក្រាបខាងលើយកអ័ក្សដេកតាងសាលា និងអ័ក្សឈរតាងអត្រាជាប់គិតជាភាគរយ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ដោយ \\(20.83&gt;20&gt;18.95\\) ដូចនេះ សាលា \\(M\\) មានអត្រាសិស្សជាប់ច្រើនជាងគេ។</div></li></ul><p>ដូចនេះ អត្រាជាប់គឺ \\(20.83\\%\\), \\(20\\%\\) និង \\(18.95\\%\\) ហើយសាលា \\(M\\) ខ្ពស់ជាងគេ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. ក្រាបសសរ</p><h2>ប្រតិបត្តិ 2</h2><p>៖ <br> បកស្រាយក្រាបសសរភ្លោះខាងក្រោមដែលបង្ហាញពីផែនការចំណាយនិងសន្សំក្នុងរយៈពេល 4 ខែ ។</p><table class=\"ts-table\"><tr><td>បរិយាយ</td><td>មករា</td><td>កុម្ភៈ</td><td>មីនា</td><td>មេសា</td></tr><tr><td>ចំណាយ (៛)</td><td>3 000 000</td><td>2 800 000</td><td>3 200 000</td><td>3 300 000</td></tr><tr><td>សន្សំ (៛)</td><td>1 000 000</td><td>1 200 000</td><td>800 000</td><td>700 000</td></tr></table><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>តើផែនការចំណាយច្រើនជាងគេនៅក្នុងខែណា?</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តើផែនការសន្សំច្រើនជាងគេនៅក្នុងខែណា?</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>តើផែនការចំណាយរយៈពេល 4 ខែមានចំនួនសរុបប៉ុន្មាន?</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>តើផែនការសន្សំរយៈពេល 4 ខែមានចំនួនសរុបប៉ុន្មាន?</div></li><li class=\"lab\"><span class=\"lb\">ង.</span><div>ចូរពណ៌នាអំពីផែនការចំណាយធៀបនឹងផែនការសន្សំ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. ក្រាបសសរ</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ខែមេសាមានផែនការចំណាយច្រើនជាងគេ គឺ \\(3~300~000\\) ៛។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ខែកុម្ភៈមានផែនការសន្សំច្រើនជាងគេ គឺ \\(1~200~000\\) ៛។</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>ចំណាយសរុបរយៈពេល \\(4\\) ខែ ៖ \\[\\begin{aligned}\n    C&amp;=3~000~000+2~800~000 \\\\\n     &amp;\\quad+3~200~000+3~300~000 \\\\\n     &amp;=12~300~000~\\text{៛}\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>សន្សំសរុបរយៈពេល \\(4\\) ខែ ៖ \\[\\begin{aligned}\n    S&amp;=1~000~000+1~200~000 \\\\\n     &amp;\\quad+800~000+700~000 \\\\\n     &amp;=3~700~000~\\text{៛}\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ង.</span><div>គ្រប់ខែ ចំណាយច្រើនជាងការសន្សំ ហើយចំណាយបូកសន្សំស្មើ \\(4~000~000\\) ៛។ នៅពេលចំណាយកើន ការសន្សំថយ។ ឧទាហរណ៍ ខែមេសាចំណាយខ្ពស់ជាងគេ ហើយសន្សំទាបជាងគេ។</div></li></ul><p>ដូចនេះ ចំណាយសរុប \\(12~300~000\\) ៛ និងសន្សំសរុប \\(3~700~000\\) ៛។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">1. ក្រាបសសរ</p><h2>ចំណាំ</h2><blockquote><p>ការធ្វើផែនការហិរញ្ញវត្ថុច្បាស់លាស់ជួយឱ្យអ្នកគ្រប់គ្រងប្រាក់ប្រកបដោយការទទួលខុសត្រូវនិងមានប្រាក់សម្រាប់ចំណាយក្នុងគ្រាអាសន្នឬការចំណាយធំៗដោយមិនចាំបាច់ខ្ចីប្រាក់ ។</p></blockquote>"}, {"k": "title", "html": "<p class=\"ts-kicker\">មេរៀនទី ២១</p><h1>លំហាត់</h1><p class=\"ts-sub\">ក្រាបសសរ</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១</h2><p>គេបោះគ្រាប់ឡុកឡាក់មួយដោយបោះ 36 ដងទទួលបានលទ្ធផលដូចខាងក្រោម៖ <br> 4 1 3 6 4 4 6 2 5 5 3 4 3 4 2 2 6 2 <br> 4 6 3 3 1 6 6 4 4 2 2 5 5 1 1 2 3 4 <br></p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>បំពេញតារាងខាងក្រោម ៖</div></li></ul><table class=\"ts-table\"><tr><td>លេខមុខគ្រាប់ឡុកឡាក់</td><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td><td>6</td></tr><tr><td>ចំនួនដង</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></table><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គូសក្រាបសសរតាងទិន្នន័យ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div><p>រាប់ចំនួនដងដែលលេខនីមួយៗលេចឡើង បានតារាង ៖</p><table class=\"ts-table\"><tr><td>លេខមុខគ្រាប់ឡុកឡាក់</td><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td><td>6</td></tr><tr><td>ចំនួនដង</td><td>4</td><td>7</td><td>6</td><td>9</td><td>4</td><td>6</td></tr></table><p>ផ្ទៀងផ្ទាត់ចំនួនដងសរុប ៖ \\[4+7+6+9+4+6=36\\]</p></div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>យកអ័ក្សដេកតាងលេខមុខគ្រាប់ឡុកឡាក់ពី \\(1\\) ដល់ \\(6\\) និងអ័ក្សឈរតាងចំនួនដង។ ខ្នាតមួយជំហានតាង \\(1\\) ដង។ សង់សសរមានកម្ពស់ \\(4,7,6,9,4,6\\) រៀងគ្នា ដូចក្រាបខាងលើ។</div></li></ul><p>ដូចនេះ តារាងនិងក្រាបតាងលទ្ធផលបោះទាំង \\(36\\) ដង ហើយលេខ \\(4\\) លេចឡើងច្រើនជាងគេ គឺ \\(9\\) ដង។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ២</h2><p>នៅក្នុងថ្នាក់រៀនមួយមានសិស្ស 25 នាក់ ក្នុងនោះអ្នកមានម៉ូតូ 8 នាក់ មានកង់ 5 នាក់ ក្រៅពីនេះគ្មានយានជំនិះ ។ ធ្វើតារាងបំណែងចែកទិន្នន័យ រួចសង់ក្រាបសសរ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ២</h2><p>ចំនួនសិស្សគ្មានយានជំនិះ ៖ \\[\\begin{aligned}\nn&amp;=25-8-5 \\\\\n &amp;=12~\\text{នាក់}\n\\end{aligned}\\]</p><table class=\"ts-table\"><tr><td>យានជំនិះ</td><td>ម៉ូតូ</td><td>កង់</td><td>គ្មានយានជំនិះ</td></tr><tr><td>ចំនួនសិស្ស</td><td>8</td><td>5</td><td>12</td></tr></table><p>យកអ័ក្សដេកតាងប្រភេទយានជំនិះ និងអ័ក្សឈរតាងចំនួនសិស្ស។ សង់សសរកម្ពស់ \\(8,5,12\\) រៀងគ្នា ដូចក្រាបខាងលើ។ ផ្ទៀងផ្ទាត់ ៖ \\[8+5+12=25\\] ដូចនេះ សិស្សមានម៉ូតូ \\(8\\) នាក់ មានកង់ \\(5\\) នាក់ និងគ្មានយានជំនិះ \\(12\\) នាក់។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៣</h2><p>តារាងខាងស្តាំ គឺជាលទ្ធផលដែលសិស្សសាលារៀន បី A, B និង C បានប្រឡងជាប់សញ្ញាបត្រមធ្យមសិក្សាបឋមភូមិ ។ បង្ហាញអត្រាសិស្សដែលប្រឡងជាប់តាមសាលានីមួយៗដោយក្រាបសសរ ។</p><table class=\"ts-table\"><tr><td>សាលា</td><td>A</td><td>B</td><td>C</td></tr><tr><td>ចំនួនសិស្សប្រឡង</td><td>250</td><td>300</td><td>280</td></tr><tr><td>ចំនួនសិស្សប្រឡងជាប់</td><td>49</td><td>67</td><td>43</td></tr></table>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៣</h2><p>គណនាអត្រាជាប់របស់សាលានីមួយៗ ៖ \\[\\begin{aligned}\np_A&amp;=\\frac{49}{250}\\times100\\%=19.60\\% \\\\\np_B&amp;=\\frac{67}{300}\\times100\\%\\approx22.33\\% \\\\\np_C&amp;=\\frac{43}{280}\\times100\\%\\approx15.36\\%\n\\end{aligned}\\] យកអ័ក្សដេកតាងសាលា \\(A,B,C\\) និងអ័ក្សឈរតាងអត្រាជាប់គិតជាភាគរយ។ សង់សសរដោយប្រើតម្លៃខាងលើ។ ដូចនេះ អត្រាជាប់គឺ \\(19.60\\%\\), \\(22.33\\%\\) និង \\(15.36\\%\\) រៀងគ្នា។ សាលា \\(B\\) មានអត្រាជាប់ខ្ពស់ជាងគេ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៤</h2><p>ស្រង់ចំនួនសិស្សក្នុងថ្នាក់រៀន អ្នកមានបងប្អូនបង្កើតឬគ្មានដាក់ក្នុងតារាងដូចខាងស្តាំ រួចតាងទិន្នន័យជាក្រាបសសរ ។</p><table class=\"ts-table\"><tr><td>ចំនួនបងប្អូន</td><td>0</td><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td></tr><tr><td>ចំនួនសិស្ស</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></table>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៤ <span class=\"ts-pg\">(១/២)</span></h2><p>លំហាត់នេះតម្រូវឱ្យស្រង់ទិន្នន័យក្នុងថ្នាក់រៀនផ្ទាល់។ សៀវភៅមិនបានផ្តល់ចំនួនសិស្សក្នុងក្រុមនីមួយៗទេ ដូចនេះមិនមានចម្លើយជាលេខតែមួយឡើយ។</p><ul class=\"ts-bullets\"><li>សួរសិស្សម្នាក់ៗអំពីចំនួនបងប្អូនបង្កើតរបស់ខ្លួន ដោយមិនរាប់ខ្លួនឯង។</li><li>តាង \\(n_0,n_1,n_2,n_3,n_4,n_5\\) ជាចំនួនសិស្សដែលមានបងប្អូន \\(0,1,2,3,4,5\\) នាក់រៀងគ្នា។ បំពេញតារាងតាមចំនួនដែលរាប់បាន។</li></ul><table class=\"ts-table\"><tr><td>ចំនួនបងប្អូន</td><td>0</td><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td></tr><tr><td>ចំនួនសិស្ស</td><td>\\(n_0\\)</td><td>\\(n_1\\)</td><td>\\(n_2\\)</td><td>\\(n_3\\)</td><td>\\(n_4\\)</td><td>\\(n_5\\)</td></tr></table>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៤ <span class=\"ts-pg\">(២/២)</span></h2><p>ផ្ទៀងផ្ទាត់ថា ផលបូកប្រេកង់ស្មើចំនួនសិស្សដែលបានស្រង់ ៖ \\[N=n_0+n_1+n_2+n_3+n_4+n_5\\] យកអ័ក្សដេកតាងចំនួនបងប្អូន និងអ័ក្សឈរតាងចំនួនសិស្ស។ ជ្រើសខ្នាតស្មើៗគ្នាដែលសមនឹងចំនួនធំបំផុត ហើយសង់សសរមានកម្ពស់ \\(n_0\\) ដល់ \\(n_5\\)។ បើមានសិស្សដែលមានបងប្អូនលើស \\(5\\) នាក់ ត្រូវបន្ថែមជួរឈរតាមចំនួនពិត។ ដូចនេះ តារាងនិងក្រាបត្រូវបំពេញតាមទិន្នន័យពិតរបស់ថ្នាក់ ដោយមិនបង្កើតចំនួនសិស្សឡើងដោយខ្លួនឯង។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៥</h2><p>ក្រាបសសរនេះបង្ហាញពីការចូលចិត្តរបស់សិស្សខាងផ្នែកកីឡាក្នុងសាលារៀនមួយ ។ <br></p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>តើប្រភេទកីឡាណាដែលសិស្សចូលចិត្តជាងគេ ហើយមានប៉ុន្មានភាគរយ?</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>រកចំនួនសិស្សសរុបក្នុងសាលារៀននោះ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៥</h2><p>ចំនួនសិស្សតាមក្រាបគឺ ឡើងខ្សែពួរ \\(100\\) នាក់ រត់ប្រណាំង \\(350\\) នាក់ លោតកម្ពស់ \\(200\\) នាក់ និងលោតចម្ងាយ \\(250\\) នាក់។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>រត់ប្រណាំងមានអ្នកចូលចិត្តច្រើនជាងគេ គឺ \\(350\\) នាក់។ ដើម្បីរកភាគរយ គណនាចំនួនសិស្សសរុបជាមុន ៖ \\[\\begin{aligned}\n    N&amp;=100+350+200+250 \\\\\n     &amp;=900~\\text{នាក់} \\\\\n    p&amp;=\\frac{350}{900}\\times100\\% \\\\\n     &amp;\\approx38.89\\%\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ចំនួនសិស្សសរុបគឺ \\(900\\) នាក់។</div></li></ul><p>ដូចនេះ កីឡារត់ប្រណាំងមានអ្នកចូលចិត្តច្រើនជាងគេ ប្រហែល \\(38.89\\%\\) ហើយមានសិស្សសរុប \\(900\\) នាក់។ ការបូកនេះយកតាមន័យលំហាត់ថា សិស្សម្នាក់ត្រូវបានរាប់ក្នុងកីឡាមួយប៉ុណ្ណោះ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៦</h2><p>នេះជាតារាងបំណែងចែកនៃការលក់ថាសចម្រៀង 3 ប្រភេទគឺ CD, VCD និង DVD ។</p><table class=\"ts-table\"><tr><td>ត្រីមាស</td><td>CD</td><td>VCD</td><td>DVD</td></tr><tr><td>ទី 1</td><td>40</td><td>70</td><td>75</td></tr><tr><td>ទី 2</td><td>55</td><td>60</td><td>80</td></tr><tr><td>ទី 3</td><td>45</td><td>65</td><td>85</td></tr></table><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>បកស្រាយទិន្នន័យខាងលើជាក្រាបសសរភ្លោះ</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តើក្នុងត្រីមាសណាគេលក់ DVD បានច្រើនជាងគេ ហើយបានប៉ុន្មានបន្ទះ ?</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៦</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div><p>យកអ័ក្សដេកតាងត្រីមាស និងអ័ក្សឈរតាងចំនួនថាសចម្រៀង។ មួយក្រុមមាន \\(3\\) សសរ តាង \\(CD,VCD,DVD\\)។ ប្រើពណ៌ឬសញ្ញាផ្សេងគ្នា និងមានបញ្ជីសម្គាល់ដូចក្រាបខាងលើ។</p><ul class=\"ts-bullets\"><li>ត្រីមាសទី \\(1\\) ៖ \\(40,70,75\\) បន្ទះ។</li><li>ត្រីមាសទី \\(2\\) ៖ \\(55,60,80\\) បន្ទះ។</li><li>ត្រីមាសទី \\(3\\) ៖ \\(45,65,85\\) បន្ទះ។</li></ul></div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ប្រៀបធៀបការលក់ \\(DVD\\) ៖ \\[85&gt;80&gt;75\\] ដូចនេះ ត្រីមាសទី \\(3\\) លក់ \\(DVD\\) បានច្រើនជាងគេ គឺ \\(85\\) បន្ទះ។</div></li></ul><p>ដូចនេះ ក្រាបមានបីក្រុមសសរ ហើយការលក់ \\(DVD\\) ខ្ពស់បំផុតនៅត្រីមាសទី \\(3\\)។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៧</h2><p>នេះជាតារាងបំណែងចែកចំនួនសិស្សប្រុសនិងចំនួនសិស្សស្រីសម្រាប់ថ្នាក់ទី 7 ក្នុងសាលារៀនមួយ ។</p><table class=\"ts-table\"><tr><td>ថ្នាក់ទី</td><td>7 ក</td><td>7 ខ</td><td>7 គ</td><td>7 ឃ</td></tr><tr><td>ប្រុស</td><td>25</td><td>18</td><td>20</td><td>19</td></tr><tr><td>ស្រី</td><td>14</td><td>16</td><td>17</td><td>20</td></tr></table><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គូសក្រាបសសរភ្លោះតាងទិន្នន័យខាងលើ</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តើក្នុងថ្នាក់ទី 7 ក មានសិស្សប្រុសលើសសិស្សស្រីប៉ុន្មានភាគរយ?</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៧</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>យកអ័ក្សដេកតាងថ្នាក់ទី \\(7\\) ក, \\(7\\) ខ, \\(7\\) គ និង \\(7\\) ឃ។ អ័ក្សឈរតាងចំនួនសិស្ស។ មួយក្រុមមានពីរសសរ តាងសិស្សប្រុសនិងសិស្សស្រី ដូចក្រាបខាងលើ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ថ្នាក់ទី \\(7\\) ក មានសិស្សប្រុស \\(25\\) នាក់ និងសិស្សស្រី \\(14\\) នាក់។ ចំនួនប្រុសលើសស្រី ៖ \\[25-14=11~\\text{នាក់}\\] បកស្រាយ «ប្រុសលើសស្រីប៉ុន្មានភាគរយ» ដោយយកចំនួនសិស្សស្រីជាគោលប្រៀបធៀប ៖ \\[\\begin{aligned}\n    p&amp;=\\frac{25-14}{14}\\times100\\% \\\\\n     &amp;=\\frac{11}{14}\\times100\\% \\\\\n     &amp;\\approx78.57\\%\n    \\end{aligned}\\]</div></li></ul><p>ដូចនេះ សិស្សប្រុសលើសសិស្សស្រីប្រហែល \\(78.57\\%\\) ធៀបនឹងចំនួនសិស្សស្រី។</p><p><b>សម្គាល់</b> បើគេចង់សួរភាពខុសគ្នានៃភាគរយប្រុសនិងស្រីក្នុងថ្នាក់ទាំងមូល គោលប្រៀបធៀបគឺ \\(25+14=39\\) នាក់។ គេបាន ៖ \\[\\frac{25-14}{39}\\times100\\%\\approx28.21\\%\\] នេះជាភាពខុសគ្នា \\(28.21\\) ពិន្ទុភាគរយ មិនមែនអត្រាប្រុសលើសស្រីដែលយកស្រីជាគោលទេ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៨</h2><p>នេះជាតារាងទិន្នន័យនៃប្រភេទកីឡានីមួយៗនិងអ្នកគាំទ្រក្នុងទីក្រុងមួយ ។</p><table class=\"ts-table\"><tr><td>ប្រភេទកីឡា</td><td>បាល់ទាត់</td><td>បាល់បោះ</td><td>បាល់ទះ</td><td>វាយសី</td><td>ហែលទឹក</td></tr><tr><td>ចំនួនអ្នកគាំទ្រជាបុរស</td><td>1200</td><td>570</td><td>700</td><td>500</td><td>400</td></tr><tr><td>ចំនួនអ្នកគាំទ្រជាស្ត្រី</td><td>800</td><td>400</td><td>350</td><td>400</td><td>105</td></tr></table><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គូសក្រាបសសរភ្លោះតាងទិន្នន័យខាងលើ</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តើប្រភេទកីឡាណាដែលមានអ្នកគាំទ្រជាបុរសច្រើនជាងគេ ហើយមានប៉ុន្មានភាគរយ?</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>តើប្រភេទកីឡាណាដែលមានអ្នកគាំទ្រជាស្ត្រីតិចជាងគេ ហើយមានប៉ុន្មានភាគរយ?</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>រកចំនួនអ្នកគាំទ្រកីឡាសរុបក្នុងទីក្រុងនេះ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៨ <span class=\"ts-pg\">(១/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>អ័ក្សដេកតាងប្រភេទកីឡាទាំង \\(5\\) និងអ័ក្សឈរតាងចំនួនអ្នកគាំទ្រ។ ក្នុងកីឡានីមួយៗ សង់ពីរសសរតាងបុរសនិងស្ត្រី ដូចក្រាបខាងលើ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>បាល់ទាត់មានអ្នកគាំទ្រជាបុរសច្រើនជាងគេ គឺ \\(1~200\\) នាក់។ យកអ្នកគាំទ្រជាបុរសទាំងអស់ជាគោល ៖ \\[\\begin{aligned}\n    M&amp;=1~200+570+700 \\\\\n     &amp;\\quad+500+400 \\\\\n     &amp;=3~370~\\text{នាក់} \\\\\n    p_M&amp;=\\frac{1~200}{3~370}\\times100\\% \\\\\n       &amp;\\approx35.61\\%\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>ហែលទឹកមានអ្នកគាំទ្រជាស្ត្រីតិចជាងគេ គឺ \\(105\\) នាក់។ យកអ្នកគាំទ្រជាស្ត្រីទាំងអស់ជាគោល ៖ \\[\\begin{aligned}\n    F&amp;=800+400+350 \\\\\n     &amp;\\quad+400+105 \\\\\n     &amp;=2~055~\\text{នាក់} \\\\\n    p_F&amp;=\\frac{105}{2~055}\\times100\\% \\\\\n       &amp;\\approx5.11\\%\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>ចំនួនអ្នកគាំទ្រសរុបតាមតារាង ៖ \\[\\begin{aligned}\n    N&amp;=M+F \\\\\n     &amp;=3~370+2~055 \\\\\n     &amp;=5~425~\\text{នាក់}\n    \\end{aligned}\\]</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៨ <span class=\"ts-pg\">(២/២)</span></h2><p>ដូចនេះ បុរសគាំទ្របាល់ទាត់ច្រើនជាងគេ (\\(35.61\\%\\) នៃបុរសទាំងអស់) ស្ត្រីគាំទ្រហែលទឹកតិចជាងគេ (\\(5.11\\%\\) នៃស្ត្រីទាំងអស់) និងអ្នកគាំទ្រសរុប \\(5~425\\) នាក់។</p><p><b>សម្គាល់</b> សំណួរមិនបញ្ជាក់គោលភាគរយ។ បើគិតក្នុងកីឡានីមួយៗវិញ បុរសក្នុងកីឡាបាល់ទាត់មាន \\(\\frac{1200}{1200+800}\\times100\\%=60\\%\\) និងស្ត្រីក្នុងកីឡាហែលទឹកមាន \\(\\frac{105}{400+105}\\times100\\%\\approx20.79\\%\\)។ ចំនួនសរុប \\(5~425\\) នាក់សន្មតថាមនុស្សម្នាក់ត្រូវបានរាប់តែមួយដង។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៩</h2><p>បុរសម្នាក់មានប្រាក់ចំណូលប្រចាំខែ 1 400 000 ៛ ហើយមានការចំណាយប្រចាំខែមួយចំនួន ។ គាត់ចង់ទិញម៉ូតូមួយគ្រឿងថ្លៃ 4 000 000 ៛ ។ តើគាត់ត្រូវចំណាយពេលសន្សំប្រាក់ប៉ុន្មានខែដើម្បីសម្រេចគោលដៅទិញម៉ូតូរបស់គាត់? គាត់មានការចំណាយប្រាក់ខែមួយចំនួនដូចបង្ហាញក្នុងក្រាបខាងក្រោម៖</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៩</h2><p>គណនាចំណាយប្រចាំខែទាំងអស់តាមក្រាប ៖ \\[\\begin{aligned}\nC&amp;=320~000+160~000+40~000 \\\\\n &amp;\\quad+100~000+180~000+200~000 \\\\\n &amp;=1~000~000~\\text{៛}\n\\end{aligned}\\] ប្រាក់ដែលអាចសន្សំបានក្នុងមួយខែ ៖ \\[\\begin{aligned}\nS&amp;=1~400~000-1~000~000 \\\\\n &amp;=400~000~\\text{៛}\n\\end{aligned}\\] ចំនួនខែដែលត្រូវសន្សំ ៖ \\[\\begin{aligned}\nn&amp;=\\frac{4~000~000}{400~000} \\\\\n &amp;=10~\\text{ខែ}\n\\end{aligned}\\] ដូចនេះ គាត់ត្រូវសន្សំប្រាក់រយៈពេល \\(10\\) ខែ ដោយសន្មតថាមិនទាន់មានប្រាក់សន្សំ ចំណូលនិងចំណាយនៅដដែល ហើយមិនគិតការប្រាក់និងការចំណាយបន្ថែម។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១០</h2><p>គ្រួសារមួយមានផែនការចំណាយប្រចាំឆ្នាំដូចក្នុងតារាងខាងក្រោម៖</p><table class=\"ts-table\"><tr><td>ការចំណាយ</td><td>ចំនួនទឹកប្រាក់</td></tr><tr><td>កាតទូរសព្ទ</td><td>800 000 ៛</td></tr><tr><td>ម្ហូបអាហារ</td><td>6 000 000 ៛</td></tr><tr><td>អគ្គិសនី</td><td>700 000 ៛</td></tr><tr><td>សម្លៀកបំពាក់</td><td>1 000 000 ៛</td></tr><tr><td>សាំងម៉ូតូ</td><td>1 500 000 ៛</td></tr><tr><td>ជួសជុលផ្ទះ</td><td>5 000 000 ៛</td></tr><tr><td>ទូទាត់សងប្រាក់កម្ចីធនាគារ</td><td>4 000 000 ៛</td></tr></table><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ចូរសង់ក្រាបសសរអំពីផែនការចំណាយប្រចាំឆ្នាំ ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តើគ្រួសារនេះត្រូវការចំណូលប្រចាំឆ្នាំប៉ុន្មានសម្រាប់ការចំណាយនេះ?</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>ចូរបកស្រាយក្រាបសសរ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១០ <span class=\"ts-pg\">(១/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>យកអ័ក្សដេកតាងប្រភេទចំណាយ និងអ័ក្សឈរតាងទឹកប្រាក់គិតជារៀល។ ខ្នាតមួយជំហានស្មើ \\(1~000~000\\) ៛។ សង់សសរតាមទិន្នន័យក្នុងតារាង ដូចក្រាបខាងលើ។</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ប្រាក់ចំណូលប្រចាំឆ្នាំត្រូវគ្រប់គ្រាន់សម្រាប់ចំណាយសរុប ៖ \\[\\begin{aligned}\n    T&amp;=800~000+6~000~000 \\\\\n     &amp;\\quad+700~000+1~000~000 \\\\\n     &amp;\\quad+1~500~000+5~000~000 \\\\\n     &amp;\\quad+4~000~000 \\\\\n     &amp;=19~000~000~\\text{៛}\n    \\end{aligned}\\] ដូចនេះ គ្រួសារត្រូវការចំណូលយ៉ាងតិច \\(19~000~000\\) ៛ ក្នុងមួយឆ្នាំសម្រាប់ចំណាយទាំងនេះ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១០ <span class=\"ts-pg\">(២/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">គ.</span><div>ម្ហូបអាហារចំណាយច្រើនជាងគេ គឺ \\(6~000~000\\) ៛ បន្ទាប់មកជួសជុលផ្ទះ \\(5~000~000\\) ៛ និងទូទាត់សងប្រាក់កម្ចីធនាគារ \\(4~000~000\\) ៛។ អគ្គិសនីចំណាយតិចជាងគេ គឺ \\(700~000\\) ៛។ ចំណាយបីប្រភេទធំបំផុតសរុប ៖ \\[\\begin{aligned}\n    T_3&amp;=6~000~000+5~000~000 \\\\\n       &amp;\\quad+4~000~000 \\\\\n       &amp;=15~000~000~\\text{៛}\n    \\end{aligned}\\] គ្រួសារអាចប្រើក្រាបនេះដើម្បីប្រៀបធៀបចំណាយ និងរៀបចំផែនការចំណូលឱ្យគ្រប់គ្រាន់។</div></li></ul><p>ដូចនេះ ផែនការចំណាយប្រចាំឆ្នាំសរុប \\(19~000~000\\) ៛ ហើយម្ហូបអាហារជាចំណាយធំបំផុត។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">មេរៀនទី ២១</p><h1>ចប់មេរៀន</h1><p class=\"ts-sub\">ក្រាបសសរ</p>"}];
